from pathlib import Path
from docx import Document
from docx.shared import Pt
import zipfile
root=Path('russian-royale/docs/game-prompts')
out=root/'Word-v2';out.mkdir(exist_ok=True)
items=[('09','broken-text','Испорченный текст'),('01','mafia','Мафия'),('02','bunker','Бункер'),('03','durak','Дурак')]
for number,slug,name in items:
 d=Document(root/'Word'/f'{number}_{slug}_Промт.docx')
 for p in d.paragraphs:
  if 'Сначала реализуй весь цикл, затем проверь его и только после этого сформируй архив.' in p.text:
   p.text=f'Итоговая поставка: russian-royale-{slug}-v1.zip. Сохраняй промежуточные ZIP с самого начала. Передай рабочую базовую версию до расширения графики и повторных длительных проверок. Полные требования ниже остаются целью; незавершённые пункты перечисляй в STATUS.md, не выдавая промежуточную версию за готовую.'
  if 'пока отмеченных «В разработке»' in p.text:
   p.text=p.text.replace('пока отмеченных «В разработке»','для которых создаются подключаемые модули')
 anchor=d.paragraphs[0]
 additions=[('Title',f'Игра {number} {name}'),('Normal','Полное задание для нейросети и инструкция передачи файлов\nРедакция от 31 октября 2026 года'),('Heading 1','Что нужно получить и зачем'),('Normal',f'Разработай одну игру «{name}» для существующего сайта «Русский Royale». Пользователь передаст полученные исходники интегратору сайта. Интегратор проверит безопасность, подключит модуль к действующим аккаунтам, серверам и учебным заданиям и опубликует его. ZIP — контейнер исходников для передачи; сам по себе он не устанавливает игру на сайт. Не создавай другой сайт вместо модуля и не запрашивай пароли или доступ к Cloudflare.'),('Normal','Этот документ содержит полные игровые правила, технический контракт, художественное задание и проверки. Работай только над этой игрой. Если приложены уже созданные файлы, сначала изучи их и продолжи работу. Не начинай всё заново. Инструкции этой вводной части заменяют прежний порядок «архив только после всех улучшений».'),('Heading 1','Как работать и сохранять результат'),('Normal','Этап 1. Проверь, можешь ли ты создавать файлы и выдавать скачиваемые вложения. Создай структуру проекта по контракту ниже, README.ru.md и STATUS.md. Сразу сохрани первый архив с пометкой checkpoint. Он может быть неполным: это резервная копия, а не готовая игра.'),('Normal','Этап 2. Реализуй минимальный полный цикл: создание комнаты, вход нескольких реальных игроков, запуск, ходы или ответы, результат и повторная партия. Добавь серверную проверку действий и защиту скрытых данных сразу. Проверь сборку и основной сценарий. Обнови STATUS.md, упакуй и выдай архив пользователю, прежде чем расширять графику.'),('Normal','Этап 3. Доведи все правила и режимы из основного задания, добавь собственное оформление и анимации, редактор контента, мобильный интерфейс и целевые проверки. После каждого законченного этапа сохраняй новый архив. Проверяй изменённые функции; не повторяй весь набор без причины.'),('Normal','Этап 4. Проверь итоговую поставку после распаковки в чистую папку. Выдай финальный ZIP и кратко укажи, что готово, что проверено и что осталось. Если лимит близок или работа прервана, передай текущее состояние с точным списком недоделок. Нельзя обещать фоновые действия после завершения ответа.'),('Heading 1','Как именно создать и передать ZIP'),('Normal',f'Финальное имя: russian-royale-{slug}-v1.zip. Промежуточные копии называй russian-royale-{slug}-checkpoint-01.zip, затем 02 и далее. В корне архива должны лежать README.ru.md, STATUS.md, integration.json и папки из технического контракта. Не вкладывай предыдущие ZIP друг в друга.'),('Normal','Упаковывай настоящие файлы средствами доступной среды: например, Python zipfile с ZIP_DEFLATED. До упаковки сохрани все редакторы. Добавляй файлы с относительными путями внутри папки проекта. После упаковки открой ZIP, проверь список файлов и целостность (ZipFile.testzip), распакуй в отдельную папку и проверь наличие исходников и инструкции запуска. Не включай node_modules, личные данные, токены, .env и базы пользователей.'),('Normal','README.ru.md должен содержать команды установки, запуска preview и тестов, необходимые версии среды и порядок подключения. STATUS.md должен отдельно перечислять реализованное, незавершённое, известные ошибки и следующий шаг. TEST-REPORT.md должен указывать только реально запущенные проверки, их результаты и ограничения. При ошибке сборки передай архив с честным предупреждением, не скрывай её.'),('Normal','Передай ZIP как скачиваемое вложение или через поддерживаемую средой ссылку на существующий файл. Упоминание /workspace/имя.zip в тексте не равно передаче файла. Не выдумывай ссылки. Если вложения недоступны, сразу объясни ограничение и передавай полные исходники по файлам с точными путями и списком уже переданного. Не отправляй огромный base64 вместо архива.'),('Heading 1','Инструкция владельцу сайта'),('Normal','Отправьте этот документ целиком в отдельный чат для одной игры. Когда появится ZIP, скачайте его в приложение «Файлы» на телефоне или в папку на компьютере. Проверьте, что файл действительно сохранился и имеет расширение .zip. Затем прикрепите его в чат разработки «Русского Royale» с сообщением «Подключи эту игру». Не отправляйте скриншот вместо архива. Сохраните свою копию до завершения подключения.'),('Normal','Если нейросеть остановилась по лимиту, после восстановления доступа напишите в том же чате: «Не начинай заново. Найди сохранённые исходники этой игры, обнови STATUS.md, упакуй текущее состояние и сразу выдай скачиваемый ZIP. Сначала передай файлы, потом продолжай улучшения». Это не снимает лимит, но задаёт правильный приоритет продолжения.'),('Heading 1','Полное техническое задание')]
 for style,text in additions:
  p=anchor.insert_paragraph_before(text,style)
  if style=='Title':p.paragraph_format.space_after=Pt(12)
 d.save(out/f'{number}_{slug}_Полное_задание.docx')
with zipfile.ZipFile(out/'Промты_9_1_2_3_Word.zip','w',zipfile.ZIP_DEFLATED) as z:
 for p in out.glob('*.docx'):z.write(p,p.name)
print(out.resolve())
